const CACHE_NAME="gys-cache-v81",APP_VERSION="3.8.27";self.addEventListener("install",t=>{self.skipWaiting()}),self.addEventListener("activate",t=>{t.waitUntil(caches.keys().then(s=>Promise.all(s.map(e=>{if(e!==CACHE_NAME)return caches.delete(e)}))).then(()=>self.clients.claim()))}),self.addEventListener("message",t=>{if(t.data&&t.data.type==="GET_VERSION"){if(t.ports&&t.ports[0])try{t.ports[0].postMessage({type:"VERSION",version:APP_VERSION})}catch{}if(t.source)try{t.source.postMessage({type:"VERSION",version:APP_VERSION})}catch{}}t.data&&t.data.type==="CLEAR_CACHE"&&caches.keys().then(s=>Promise.all(s.map(e=>caches.delete(e)))).then(()=>{if(t.ports&&t.ports[0])try{t.ports[0].postMessage({type:"CACHE_CLEARED"})}catch{}if(t.source)try{t.source.postMessage({type:"CACHE_CLEARED"})}catch{}})}),self.addEventListener("fetch",t=>{if(t.request.method==="GET"){var s;try{s=new URL(t.request.url)}catch{return}if(s.pathname.includes("/midi/")||s.pathname.includes("/pdf/")||s.pathname.includes("/chord/")||s.pathname.includes("assets-list.json")||s.pathname.includes("assets-lyrics.json")||s.pathname.includes("assets-chord-list.json")||s.pathname.endsWith(".sf2")||s.pathname.endsWith(".sf3")){t.respondWith(fetch(t.request));return}var e=s.origin===self.location.origin&&(s.pathname.endsWith(".js")||s.pathname.endsWith(".css")||s.pathname.endsWith(".html")||s.pathname==="/"||s.pathname.endsWith("/"));if(e){t.respondWith(caches.open(CACHE_NAME).then(r=>fetch(t.request).then(a=>(a&&a.status===200&&r.put(t.request,a.clone()),a)).catch(()=>caches.match(t.request).then(a=>a||Response.error()))));return}t.respondWith(caches.match(t.request).then(r=>r||fetch(t.request).then(a=>{if(a&&(a.status===200||a.type==="opaque")){var c=a.clone();caches.open(CACHE_NAME).then(i=>{i.put(t.request,c)})}return a}).catch(()=>Response.error())))}});
